const fs=require('fs'),path=require('path'),crypto=require('crypto');
const root=process.cwd(),dir=__dirname,v=path.join(dir,'verification');
const read=p=>fs.readFileSync(path.join(root,p),'utf8');
const json=p=>JSON.parse(fs.readFileSync(path.join(dir,p),'utf8'));
const write=(name,text)=>fs.writeFileSync(path.join(dir,name),text.trim()+'\n');
const link=(p,label=path.basename(p))=>`[${label}](<${path.join(root,p).replaceAll('\\','/')}>)`;
const report=(p,label=p)=>`[${label}](<${path.join(dir,p).replaceAll('\\','/')}>)`;
const refs=[];
function L(p,needle,label){const s=read(p);const offset=needle?s.indexOf(needle):0;if(offset<0)throw Error('Missing citation anchor '+p+': '+needle);const n=s.slice(0,offset).split('\n').length;refs.push({file:p,line:n,anchor:needle||null});return `[${label||p+':'+n}](<${path.join(root,p).replaceAll('\\','/')}:${n}>)`;}
const csv=rows=>{const keys=Object.keys(rows[0]);return [keys,...rows.map(r=>keys.map(k=>Array.isArray(r[k])?r[k].join('; '):r[k]??''))].map(row=>row.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\n');};
const inv=json('verification/inventory-summary.json'),models=json('verification/schema-model-details.json');
const testFiles=fs.readdirSync(v).filter(p=>/^tests-(commerce|people|finance|platform|supplement)-direct\.jest\.json$/.test(p));
const tests=testFiles.map(p=>({file:p,...json('verification/'+p)}));
const totals=tests.reduce((a,t)=>({suites:a.suites+t.numTotalTestSuites,passed:a.passed+t.numPassedTests,failed:a.failed+t.numFailedTests,pending:a.pending+t.numPendingTests}),{suites:0,passed:0,failed:0,pending:0});
const testTable=tests.map(t=>`| ${t.file.replace('tests-','').replace('-direct.jest.json','')} | ${t.numTotalTestSuites} | ${t.numPassedTests} | ${t.numFailedTests} | ${t.numPendingTests} |`).join('\n');
const C={queue:L('lib/pos/offline-local-queue.ts','export'),hook:L('hooks/posHooks/useOfflineSync.ts','SYNCING'),replay:L('services/pos/offline-sync.service.ts','function isOfflinePOSReplayAuthorized'),fx:L('services/accounting/journals.service.ts','baseDebit: debit'),fs:L('services/accounting/financial-statements.service.ts','db.journalEntryLine.groupBy'),reverse:L('services/accounting/posting.service.ts','original.sourceType === AccountingSourceType.CUSTOMER_SETTLEMENT'),settings:L('services/accounting/accounting-settings.service.ts','export async function updateAccountingSettings'),settingsAction:L('actions/accounting/settings.actions.ts','baseCurrency: z.'),close:L('services/accounting/periods.service.ts','export async function closeAccountingPeriod'),period:L('services/accounting/periods.service.ts','export'),gl:L('services/accounting/reports.service.ts','let runningBalance = decimalZero()'),journal:L('prisma/schema.prisma','model JournalEntry {'),country:L('services/regulatory/country-packs/cameroon.ts','const CNPS_CAPABILITY_STATUS'),analytics:L('services/analytics/financial-analytics.service.ts','FINANCIAL_SOURCES_NOT_CONNECTED'),ap:L('services/purchasing/ap-control.service.ts'),stock:L('services/inventory/inventory-stock-event.service.ts'),hris:L('services/hris/org.service.ts','export'),payroll:L('services/payroll/payroll-control.service.ts'),outbox:L('services/events/business-event-outbox.service.ts'),runbook:L('docs/operations/runbooks/RUNBOOK.md','UPDATE "User"'),gate:L('scripts/payroll-trust-spine-readiness-gate.js','id: "cas_idempotency_and_partial_commit_regressions_covered"'),reportGate:L('scripts/report-trust-export-gate.js','id: "analytics_currency_is_service_owned"')};
const findings=[
{id:'F01',sev:'P1',kind:'Implementation defect',status:'Incorrect for non-unit FX',title:'Foreign-currency posting and financial statements disagree with base-currency semantics',outcome:'Professional accounts and financial BI can be balanced but materially misstated.',scenario:'A manual entry for 100 EUR with illustrative rate 655.957 stores baseDebit=100 instead of 65,595.70. In a separate report probe, 100 EUR and 100 XAF on the same account become 200.00 XAF, rather than 65,695.70 XAF.',evidence:`${C.fx}; ${C.fs}; ${report('verification/accounting-behavior-probes.json')} (FX_BASE_AMOUNT, REPORT_CURRENCY_MIX).`,confidence:'High: actual current service functions with synthetic transaction doubles; the local sample contains 12 non-unit-rate lines with no conversion mismatch, so actual stored corruption was not established.',domains:'Accounting, purchasing, sales, inventory valuation, payroll postings, BI',cause:'Manual journal lines copy nominal amounts into base fields; statement aggregation sums nominal debit/credit by account and then labels the result with the organization accounting currency.',fix:'Define one immutable transaction/base currency contract, documented rate direction and rounding. Convert when recording the fact; aggregate authoritative base values for functional-currency statements. Reject unsupported or missing rates. Separately disclose transaction-currency ledgers.',migration:'Inventory historic non-unit-rate and mixed-currency entries. Reconstruct only from approved original rate evidence; make controlled corrections and invalidate affected close/export evidence. Do not silently reinterpret old rows.',owner:'Accounting kernel engineer + qualified accountant',deps:'Agreed base-currency policy; F07',test:'100 EUR plus 100 XAF produces 65,695.70 XAF under the illustrative rate; balanced journal, source amount, trial balance and statements tie out. Test reversals, rounding and missing-rate rejection.'},
{id:'F02',sev:'P1',kind:'Implementation defect',status:'Incomplete source-ownership enforcement',title:'Generic reversal can reverse source-owned POS accounting without reversing the business transaction',outcome:'The ledger may no longer agree with stock, sales or tender evidence.',scenario:'Pass a POSTED POS_SALE journal to reverseJournalEntry. The current function marks it REVERSED and creates a MANUAL reversal without invoking the sale, payment or stock owner.',evidence:`${C.reverse}; ${report('verification/accounting-behavior-probes.json')} (SOURCE_OWNED_REVERSAL).`,confidence:'High at service boundary; authorized actor was mocked. No unauthorized-access or live-money exploit was attempted.',domains:'Accounting, POS, inventory, AP, payroll',cause:'Only CUSTOMER_SETTLEMENT and PAYMENT_SUSPENSE receive explicit source-owned rejection here; the generic path accepts other economic source types.',fix:'Permit generic reversal only for explicitly eligible manually owned entries. Route business-source corrections to the owning command and preserve original/reversal/source links across every effect.',migration:'Read-only scan for generic reversals of business sources; reconcile each source before correcting. Preserve old evidence and create explicit compensating records.',owner:'Accounting and source-domain maintainers',deps:'Source-type ownership inventory; F01 for currency-safe corrections',test:'POS/AP/payroll/inventory sources cannot use generic reversal; source correction reverses the appropriate stock, obligation, tender and journal effects exactly once.'},
{id:'F03',sev:'P1',kind:'Implementation defect',status:'Local durability unsafe',title:'Concurrent offline enqueues can overwrite a sale, and corrupt storage is silently treated as empty',outcome:'A cashier can receive a successful enqueue result while a sale is absent from the durable queue.',scenario:'Two concurrent enqueues both load the same state before awaited hashing. Both return sequence 1; only the second sale remains. Separately, malformed stored JSON reloads as an empty sequence-1 queue.',evidence:`${C.queue}; ${report('verification/offline-behavior-probes.json')}.`,confidence:'High: actual queue module, WebCrypto, in-memory Storage; this proves the algorithmic lost update, not physical device or browser crash durability.',domains:'Offline POS, stock, payments, fiscal evidence',cause:'Asynchronous read-modify-write over one localStorage snapshot has no serialization across calls/tabs; parse failures erase the usable state in memory.',fix:'Use transactional durable queue storage with cross-tab coordination, monotonic sequence allocation and explicit corruption quarantine/recovery. Acknowledgement must mean durable persistence; recover without reusing identities.',migration:'Version queue storage and migrate existing pending records without dropping IDs, hashes or sequence history. Preserve corrupted payloads for authorized recovery.',owner:'Offline/edge engineer',deps:'Before enabling F05',test:'Concurrent enqueues in one and multiple tabs survive reload with all sales and unique sequences; inject storage quota, parse and write failures; no success response for non-durable sale.'},
{id:'F04',sev:'P1',kind:'Implementation defect',status:'Restart/retry recovery incomplete',title:'A sale left SYNCING can disappear from pending replay after restart or a thrown transport error',outcome:'An accepted offline sale remains unsynchronized without a working automatic recovery path.',scenario:'Persist a queue item as SYNCING, then reload. Pending count is zero and replay envelope is null. The hook marks SYNCING before awaiting the server call; thrown failures do not restore the persisted status.',evidence:`${C.hook}; ${C.queue}; ${report('verification/offline-behavior-probes.json')}.`,confidence:'High: persisted-state probe plus hook inspection; no actual browser kill or network fault was injected.',domains:'Offline POS, support operations',cause:'Only QUEUED/FAILED records are eligible; SYNCING has no expiring lease or restart reconciliation.',fix:'Add attempt identity and recoverable lease; on startup reconcile stale in-flight attempts with the server by immutable event identity before retrying. Return explicit retry/conflict states for thrown transport failures.',migration:'Recover existing SYNCING records without assigning new sale identities; reconcile already committed events first.',owner:'Offline/edge engineer + POS owner',deps:'F03 durable queue; server idempotency contract',test:'Terminate tab after send, before response, and after server commit; restart completes once without stranded entries or duplicate economic effects.'},
{id:'F05',sev:'P1 for offline release',kind:'Capability boundary / rollout gap',status:'Development-only replay',title:'Offline replay is deliberately unavailable outside the test-authorized pilot',outcome:'The current repository cannot substantiate a production offline-sales promise.',scenario:'Replay authorization requires NODE_ENV=test and AQSTOQFLOW_ENABLE_OFFLINE_POS_REPLAY_TESTS=1. Normal production use fails this gate.',evidence:`${C.replay}; ${report('verification/offline-pos-fiscal-replay-gate.json')}.`,confidence:'High static evidence. Passing the structural replay gate confirms scaffolding, not production authorization.',domains:'Offline, product packaging, rollout, provider/fiscal integration',cause:'Production admission is intentionally disabled; that is an honest boundary, but the requested business capability remains incomplete.',fix:'Keep the limitation explicit in product/support material. After F03/F04, complete disposable-database concurrency tests, real-device recovery, replay authorization and country/provider evidence before a controlled pilot.',migration:'No production flag flip or migration during audit; future enablement needs compatibility and rollback plan.',owner:'Product owner + offline lead + release assurance',deps:'F03, F04, F02, source/fiscal/provider qualification',test:'A documented production-safe pilot configuration executes full offline sale→replay→stock/tender/journal/fiscal flow, with duplicate/reordered/denied-device cases and recovery evidence.'},
{id:'F06',sev:'P1 for professional close',kind:'Implementation / workflow contract gap',status:'Period locking and assurance readiness are separate',title:'Period close can succeed while close assurance still has a blocking finding',outcome:'Users may lock an incomplete period and mistake CLOSED for evidence-complete close.',scenario:'The service probe supplies BLOCKED / INVENTORY_MISMATCH close assurance, while the narrower preflight passes. The period becomes CLOSED without reading assurance.',evidence:`${C.close}; ${report('verification/accounting-behavior-probes.json')} (CLOSE_WITHOUT_ASSURANCE_READ).`,confidence:'High for the period-close service. Certified export has a separate stronger gate; this is not a demonstrated bypass of that export gate.',domains:'Accounting close, inventory, payroll, purchasing, UX',cause:'Preflight covers drafts, unresolved batches, batch links, payment exceptions/suspense/sign-off and balance by currency; it does not consume the complete close-assurance readiness contract.',fix:'Agree whether locking is a distinct operational action or professional close. For professional close, consume authoritative source completeness, inventory/AP/payroll tie-outs and current assurance version under the period lock. If lock-only remains, clearly label it and do not propagate a readiness claim.',migration:'Re-evaluate previously CLOSED periods against current readiness; preserve historic state and append findings, with controlled reopen where needed.',owner:'Accounting close owner + product/workflow lead',deps:'F01, F02; source completion contracts',test:'Inventory/payroll/AP blocker or stale assurance prevents professional close; valid signed evidence permits it; concurrent posting versus close yields one consistent ordering.'},
{id:'F07',sev:'P1',kind:'Implementation defect',status:'Locked settings remain mutable',title:'Accounting base currency can change despite locked setup and existing ledger history',outcome:'Historical amounts can be relabeled and accounting/organization currency can diverge.',scenario:'updateAccountingSettings accepts a new baseCurrency when setupStatus=LOCKED; it performs no history or setup-lock rejection. The protected action accepts a valid three-character currency.',evidence:`${C.settings}; ${C.settingsAction}; ${report('verification/accounting-behavior-probes.json')} (LOCKED_SETTINGS_MUTATION).`,confidence:'High for valid baseCurrency updates. The probe also sends arbitrary policy text directly to the service; that does not establish action-level reachability for invalid policy values.',domains:'Accounting setup, organization settings, valuation, BI',cause:'The newer organization-profile path blocks direct currency changes, but accounting settings have a separate mutable authority.',fix:'Freeze economic settings after activation/history or implement an explicit effective-dated migration with reviewed conversion, reporting and close invalidation. Use one authoritative currency transition policy.',migration:'Compare organization/accounting currency and historical reports. Any correction requires audited migration; do not change historical denomination by configuration alone.',owner:'Accounting/platform settings owners',deps:'Currency authority decision; F01',test:'Valid currency updates fail after locked setup or ledger activity; authorized migration maintains old-period denomination and explicitly converts future periods.'},
{id:'F08',sev:'P2',kind:'Implementation defect',status:'Fiscal-boundary generation incorrect for partial first month',title:'Fiscal-year generation can create a period before the requested year starts',outcome:'Posting/date controls admit days outside the intended fiscal year.',scenario:'A fiscal year starting 15 June produces a first period beginning 1 June.',evidence:`${C.period}; ${report('verification/accounting-behavior-probes.json')} (PARTIAL_FISCAL_YEAR).`,confidence:'High synthetic service reproduction; the inspected local database has no out-of-bounds periods.',domains:'Accounting calendar, close, reporting',cause:'Monthly generation normalizes to the first of the month without clipping to fiscal-year bounds.',fix:'Clip initial/final periods to the requested year, or explicitly reject unsupported partial-month starts. Validate overlap and bounds in transaction/database controls.',migration:'Scan existing fiscal periods; do not move dates containing posted entries without reviewed correction.',owner:'Accounting engineer',deps:'Business calendar policy',test:'Mid-month start/end, leap day and adjacent years have exact bounded coverage and no overlap.'},
{id:'F09',sev:'P2',kind:'Reporting contract defect',status:'Period movement exposed as running balance',title:'General-ledger running balance omits activity before the selected start date',outcome:'An accountant can interpret period movement as the account balance.',scenario:'Opening balance 100 before the selected start plus movement 25 yields runningBalance=25; no opening query is made. A protected general-ledger action exposes this service.',evidence:`${C.gl}; ${L('actions/accounting/reports.actions.ts','const getGeneralLedgerProtected')}; ${report('verification/accounting-behavior-probes.json')} (GL_OPENING_BALANCE).`,confidence:'High for returned data; no live user screen was verified. If a consumer intentionally wants period movement, the field must say so.',domains:'Accounting reports, API/UX, BI',cause:'Accumulation starts at zero over the selected date range.',fix:'Return opening balance, movements and closing balance with explicit denomination, or rename period-only movement fields. Preserve reversed originals and corrections.',migration:'No fact migration; version report contract and invalidate/reissue misleading derived exports where required.',owner:'Accounting reporting + workflow UX',deps:'F01 currency contract',test:'Opening 100 + debit25 - credit10 closes115, with independently reconciled opening and movement totals.'},
{id:'F10',sev:'P2',kind:'Database assurance / defense gap',status:'Application enforcement carries ledger invariants',title:'Posted general-ledger evidence lacks the database protections present in newer evidence domains',outcome:'A future direct writer, maintenance error or incomplete service guard has a wider blast radius.',scenario:'Catalog inspection finds no noninternal trigger on journal_entries or journal_entry_lines. Their key relationships use plain IDs rather than tenant-composite keys; journal lines can cascade with their entry.',evidence:`${C.journal}; ${report('verification/database-metadata.json')}; ${report('verification/database-tieouts.json')}.`,confidence:'High schema/catalog evidence; no mutation exploit was attempted, and sampled line/account/entry tenant consistency passed. No RLS does not by itself establish a vulnerability.',domains:'Database, accounting, security, retention',cause:'Older ledger schema relies on services, unlike newer finalized payroll/fiscal evidence with DB immutability controls. Database roles/privileges and all dynamic writers were not proven.',fix:'First inventory legitimate writers and privileges. Add scoped posted-evidence immutability, tenant-consistent relations and controlled reversal/correction operations; formalize retention/deletion boundaries without breaking allowed draft changes.',migration:'Preflight orphans and tenant mismatches; stage NOT VALID/validation or equivalent safe migration; preserve archived evidence and test restore. Avoid blanket triggers incompatible with supported transitions.',owner:'Database engineer + accounting controls',deps:'F02 owner rules; migration/recovery evidence',test:'On disposable PostgreSQL, illegal posted edits/deletes and cross-tenant links fail, while valid draft editing/posting/source correction remain possible.'},
{id:'F11',sev:'P1 for statutory payroll release',kind:'External qualification and supported-scope limit',status:'CM only; draft/expert-review capabilities',title:'Country-pack publication does not establish complete production statutory payroll support',outcome:'A customer could overestimate the supported legal/tax scope if packaging summarizes the pack as fully ready.',scenario:'CM-2026.1 is PUBLISHED, but CNPS is SUPPORTED_DRAFT/SOURCE_CHECKED and IRPP productionCalculationSupported is false. E-invoicing also requires expert review. Registry inspection found Cameroon, not an all-OHADA ruleset.',evidence:`${C.country}; ${L('services/regulatory/country-packs/registry.ts')}; [DGI 2026 tax-code publication](https://www.impots.cm/en/node/1333).`,confidence:'High for code-declared support; no legal-rate correctness or authority acceptance certification. A newer official tax-code publication exists than the cited 2025 code; this alone does not prove any rate wrong.',domains:'Payroll, compliance, sales packaging, country adapters',cause:'Required qualified review and authority/provider evidence remain incomplete; some reference provenance needs refresh.',fix:'Maintain capability-level country/version support. Refresh official references and have qualified reviewers validate formulas, effective dates, examples and artifacts. Preserve blocked states until independent approval and acceptance evidence exist.',migration:'Version rules and snapshots; never overwrite historical payroll rule provenance. Recalculate differences only through approved correction runs.',owner:'Country-pack maintainer + independent payroll/tax expert',deps:'Reviewed source dossier; provider/authority sandbox access',test:'Reviewed golden cases for each declared family, prorations/regularization/rounding/corrections; authority artifact validation and signed qualification scoped to a specific version.'},
{id:'F12',sev:'P2',kind:'Product capability gap',status:'Financial analytics intentionally partial',title:'Professional financial and decision-support promises exceed the connected BI sources',outcome:'Users cannot obtain a complete explainable financial cockpit or a verified cash-flow statement from the current financial-metrics contract.',scenario:'financial-metrics.v2 returns FINANCIAL_SOURCES_NOT_CONNECTED and null financial statements/ratios while exposing narrower payroll evidence. Dedicated fixed-asset and budget subledgers were not found in the model inventory.',evidence:`${C.analytics}; ${L('services/bi/bi-evidence-adapter.service.ts')}; ${report('bi-capability-matrix.md')}.`,confidence:'High for explicit null/partial contract; medium for absence of whole product features based on systematic model/file inventory. Manual journals can represent entries without providing an asset-management workflow.',domains:'BI, accounting, product strategy',cause:'Operational snapshots and trust contracts are more complete than connected professional financial measures.',fix:'Complete ledger-correct financial reporting after F01/F06/F09. Prioritize margin/COGS, aging, cash/settlement exceptions and close progress before forecasts. Keep unsupported values unavailable and distinguish order activity from revenue/cash.',migration:'Version metric definitions/snapshots; rebuild derived data from corrected sources with provenance, not default zero values.',owner:'BI/data engineer + finance/product owner',deps:'F01, F06, F09, source coverage',test:'Every shipped KPI has the contract in the BI matrix and a source-to-result tie-out; absent evidence produces an explicit limitation, not a fabricated figure.'},
{id:'F13',sev:'P2',kind:'Verification maintenance / evidence gap',status:'Test and structural-gate blockers remain',title:'Readiness checks need reconciliation with current behavior',outcome:'Teams cannot use current green/red summaries as an accurate release decision without triage.',scenario:`The four main unit/service groups produced 3,061 passed and 23 failed assertions across 310 suites using the audit adapter. Eight selected structural gates passed; payroll trust-spine and report-trust gates blocked. Some failures are stale mocks or string markers, while broader runtime proof is still absent.`,evidence:`${C.gate}; ${C.reportGate}; ${report('verification-summary.md')}; ${report('verification/test-failure-register.json')}.`,confidence:'High observed outputs; failure classifications are bounded by source review and the audit-specific runner. This is not a claim that all failing checks are false positives.',domains:'QA, release assurance, accounting, payroll, reporting',cause:'Mocks omit new close/entitlement lookups or assume a prior raw-SQL argument shape; country expectations assume a stronger support state; scanners match exact implementation/test text.',fix:'Restore representative mocks and current contracts, replace brittle text checks with behavior/structured contract checks where practical, and triage remaining report gate clauses. Preserve original failing evidence; do not weaken controls or approve blocked statutory capability to make tests green.',migration:'No business-data change required; verification baselines must retain provenance and rationale.',owner:'QA lead + affected module maintainers',deps:'Confirm intended contracts; run exact repository CI in controlled environment',test:'All failures have a documented cause and regression evidence; clean exact-config CI and database/browser matrices pass without changing business safety expectations.'},
{id:'F14',sev:'P2',kind:'Operations documentation / deployed-evidence gap',status:'Runbook stale; current recovery objectives unverified',title:'Operational recovery and account-deletion instructions do not match current system evidence',outcome:'Support may run ineffective legacy instructions or lack a tested recovery path during an incident.',scenario:'RUNBOOK.md uses SQL against "User", "Account" and "Session" while current mapped tables are users/accounts/sessions, and still says no restore drill. A later 29 August local restore rehearsal exists for 80 migrations, while this audit sees 87.',evidence:`${C.runbook}; ${L('what-next/migrations/staging-primary-restore-rehearsal-2026-08-29.md')}; ${report('verification/schema-database-comparison.json')}.`,confidence:'High documentation mismatch. The older local restore is useful evidence, not current deployed PITR/RPO/RTO or functional restoration proof.',domains:'SRE, security/privacy, support, database migrations',cause:'Operational instructions and recovery evidence have not been consolidated against the current schema/release.',fix:'Replace obsolete commands with reviewed current lifecycle procedures; rehearse current-version backup restoration on an isolated target and test authentication, financial/source invariants and worker recovery. Record measured RPO/RTO, operator and date.',migration:'Use restore-only environments; no shared reset or data deletion. Retention/legal-hold policy must precede destructive account/tenant cleanup.',owner:'SRE + privacy/security + support',deps:'Current schema release; designated recovery target',test:'A new operator follows the runbook successfully on a disposable clone; deployed backup retention/PITR and restore time are evidenced; no incorrect legacy SQL remains.'},
];
write('findings.md',`# Platform correctness findings\n\nAudit date: 2026-09-30. Severity is conditional on the affected product promise. P1 means material correctness or launch blocker; P2 means bounded correctness, assurance or completeness work. These are findings from one coordinated review using the listed professional lenses, not independent expert certifications.\n\nImplementation status and evidence strength are separate. Local data is development evidence, not production.\n\n| ID | Priority | Classification | Finding |\n|---|---|---|---|\n${findings.map(f=>`| ${f.id} | ${f.sev} | ${f.kind} | ${f.title} |`).join('\n')}\n\n${findings.map(f=>`## ${f.id} — ${f.title}\n\n- **Severity / classification:** ${f.sev}; ${f.kind}.\n- **Implementation status:** ${f.status}.\n- **Business outcome:** ${f.outcome}\n- **Concrete scenario:** ${f.scenario}\n- **Evidence:** ${f.evidence}\n- **Confidence and limits:** ${f.confidence}\n- **Domains:** ${f.domains}.\n- **Cause / uncertainty:** ${f.cause}\n- **Correction:** ${f.fix}\n- **Migration / backfill:** ${f.migration}\n- **Owner:** ${f.owner}.\n- **Dependencies:** ${f.deps}.\n- **Acceptance:** ${f.test}`).join('\n\n')}\n\n## Historical finding revalidation\n\n| Historical concern | Current classification | Evidence / scope |\n|---|---|---|\n| Currency/base amounts | Confirmed | F01 reproduced on current functions; current local FX sample happens to be consistent. |\n| Source-owned reversals | Changed, still incomplete | Customer settlement and payment suspense now explicitly protected; POS_SALE still reproduced, F02. |\n| Close versus posting concurrency | Changed / static improvement | Period close takes FOR UPDATE; transactional getOpenPeriodForDate takes FOR SHARE. A concurrent PostgreSQL proof across all producers was not run. |\n| Archived accounts disappearing | Resolved in inspected reporting paths | Retained accounts and account descriptors are included; focused retained-account tests are in finance results. |\n| Reversed originals omitted | Resolved in inspected report filters | POSTED and REVERSED originals are retained with compensating entries. |\n| Organization profile currency edits | Resolved in that path, separate defect remains | Current profile update blocks uncontrolled currency changes; accounting settings still allow them, F07. |\n| Arbitrary analytics currency / truncated order totals | Changed / improved | Current order-activity service derives org currency/timezone, SQL aggregates and explicit order-activity semantics; no 1,000-row cap in that aggregation. Financial statements still have F01. |\n| General-ledger opening balance | Confirmed contract issue | F09. |\n| Partial fiscal-year boundary | Confirmed | F08; no matching local-data anomaly found. |\n| Assurance versus close status | Confirmed, bounded | F06; certified export remains a distinct gate. |\n\nEarlier reports were navigation aids. No historical READY or certification label was accepted as current deployed proof.`);

